class Solution:
    def minimumDifference(self, nums: List[int], k: int) -> int:
        ans = float('inf')
        cur = []
        for x in nums:
            cur = list({x | v for v in cur} | {x})
            for v in cur:
                ans = min(ans, abs(k - v))
        return ans

