class Solution {
public:
    int minimumDifference(vector<int>& nums, int k) {
        int ans = INT_MAX;
        vector<int> cur;
        for (int x : nums) {
            vector<int> nxt{x};
            for (int v : cur) nxt.push_back(v | x);
            sort(nxt.begin(), nxt.end());
            nxt.erase(unique(nxt.begin(), nxt.end()), nxt.end());
            cur = nxt;
            for (int v : cur) ans = min(ans, abs(k - v));
        }
        return ans;
    }
};

