class Solution:
    def minimumDifference(self, nums: List[int], k: int) -> int:
        ans = float('inf')
        last = [-1] * 31
        for r, x in enumerate(nums):
            for b in range(31):
                if x >> b & 1: last[b] = r
            vals = sorted(set(
                sum(1 << b for b in range(31) if last[b] >= l))
                for l in set(last) if l >= 0))
            for v in vals: ans = min(ans, abs(k - v))
        return ans

