class Solution {
public:
    int minimumDifference(vector<int>& nums, int k) {
        int ans = INT_MAX, last[31];
        fill(last, last + 31, -1);
        for (int r = 0; r < nums.size(); r++) {
            for (int b = 0; b < 31; b++)
                if (nums[r] >> b & 1) last[b] = r;
            set<int> ls(last, last + 31);
            ls.erase(-1);
            for (int l : ls) {
                int v = 0;
                for (int b = 0; b < 31; b++)
                    if (last[b] >= l) v |= 1 << b;
                ans = min(ans, abs(k - v));
            }
        }
        return ans;
    }
};

