class Solution {
    public int minimumDifference(int[] nums, int k) {
        int ans = Integer.MAX_VALUE;
        int[] last = new int[31];
        Arrays.fill(last, -1);
        for (int r = 0; r < nums.length; r++) {
            for (int b = 0; b < 31; b++)
                if ((nums[r] >> b & 1) == 1) last[b] = r;
            TreeSet<Integer> ls = new TreeSet<>();
            for (int v : last) if (v >= 0) ls.add(v);
            for (int l : ls) {
                int v = 0;
                for (int b = 0; b < 31; b++)
                    if (last[b] >= l) v |= 1 << b;
                ans = Math.min(ans, Math.abs(k - v));
            }
        }
        return ans;
    }
}

